import React, { memo, useEffect, useMemo, useState } from "react";

import { useAppContext } from "../context/AppContext";

const formatResourceLabel = (resource) =>
  resource.floor ? `${resource.name} - ${resource.floor}` : resource.name;

const safe = (value) =>
  typeof value === "object" ? JSON.stringify(value) : value;

const BookingForm = ({
  formData,
  onChange,
  onSubmit,
  onAvailabilityCheck,
  availabilityMsg,
  loading
}) => {
  const {
    blocks,
    resources: globalResources,
    dataLoaded,
    prefetching,
    fetchInitialData
  } = useAppContext();
  const [resources, setResources] = useState([]);
  const [resourceLoading, setResourceLoading] = useState(false);

  useEffect(() => {
    fetchInitialData();
  }, [fetchInitialData]);

  useEffect(() => {
    if (formData.resourceScope === "block" && !formData.blockId) {
      setResources([]);
      setResourceLoading(false);
      return undefined;
    }

    const cacheKey = formData.resourceScope === "extra" ? "extra" : formData.blockId;
    setResourceLoading(true);
    const timeoutId = window.setTimeout(async () => {
      setResources(globalResources[cacheKey] || []);
      setResourceLoading(false);
    }, 250);

    return () => window.clearTimeout(timeoutId);
  }, [formData.blockId, formData.resourceScope, globalResources]);

  const blockOptions = useMemo(() => blocks || [], [blocks]);

  const handleScopeChange = (value) => {
    onChange({ target: { name: "resourceScope", value } });
    onChange({ target: { name: "blockId", value: "" } });
    onChange({ target: { name: "resourceId", value: "" } });
  };

  const handleBlockChange = (event) => {
    onChange({ target: { name: "blockId", value: event.target.value } });
    onChange({ target: { name: "resourceId", value: "" } });
  };

  const scopeIsBlock = formData.resourceScope === "block";

  return (
    <div className="panel-card booking-card-shell">
      <div className="panel-header">
        <div>
          <h3>Create Booking</h3>
          <p>Pick a block or extra center, choose a resource, and reserve your slot.</p>
        </div>
      </div>

      <div className="scope-toggle">
        <button
          type="button"
          className={`scope-chip ${scopeIsBlock ? "active" : ""}`}
          onClick={() => handleScopeChange("block")}
        >
          Block
        </button>
        <button
          type="button"
          className={`scope-chip ${!scopeIsBlock ? "active" : ""}`}
          onClick={() => handleScopeChange("extra")}
        >
          Extra Centers
        </button>
      </div>

      {prefetching || !dataLoaded ? <div className="skeleton-line" aria-hidden="true" /> : null}

      <form className="grid-form" onSubmit={onSubmit}>
        {scopeIsBlock ? (
          <label>
            <span>Block</span>
            <select value={formData.blockId || ""} onChange={handleBlockChange} required disabled={prefetching || !dataLoaded}>
              <option value="">
                {prefetching || !dataLoaded ? "Loading blocks..." : blockOptions.length === 0 ? "No blocks available" : "Select block"}
              </option>
              {blockOptions.map((block) => (
                <option key={block.id} value={block.id}>
                  Block {block.name}
                </option>
              ))}
            </select>
          </label>
        ) : (
          <div className="selection-summary">
            <span>Extra Centers</span>
            <p>Book shared spaces like the Innovation Center or Main Seminar Hall.</p>
          </div>
        )}

        <label>
          <span>Resource</span>
          <select
            name="resourceId"
            value={formData.resourceId || ""}
            onChange={onChange}
            required
            disabled={resourceLoading || (scopeIsBlock ? !formData.blockId : false)}
          >
            <option value="">
              {scopeIsBlock && !formData.blockId
                ? "Select block first"
                : resourceLoading
                ? "Loading resources..."
                : resources.length === 0
                ? "No resources found"
                : "Select resource"}
            </option>
            {resources.map((resource) => (
              <option key={resource.id} value={resource.id}>
                {formatResourceLabel(resource)}
              </option>
            ))}
          </select>
        </label>

        {resourceLoading ? <div className="skeleton-line full-width" aria-hidden="true" /> : null}

        <label>
          <span>Your Name</span>
          <input
            type="text"
            name="name"
            value={formData.name || ""}
            onChange={onChange}
            placeholder="Your Name"
            required
          />
        </label>

        <label>
          <span>Department</span>
          <input
            type="text"
            name="department"
            value={formData.department || ""}
            onChange={onChange}
            placeholder="Department"
            required
          />
        </label>

        <label>
          <span>Date</span>
          <input
            type="date"
            name="bookingDate"
            value={formData.bookingDate || ""}
            onChange={onChange}
            required
          />
        </label>

        <label>
          <span>Start time</span>
          <input
            type="time"
            name="startTime"
            value={formData.startTime || ""}
            onChange={onChange}
            required
          />
        </label>

        <label>
          <span>End time</span>
          <input
            type="time"
            name="endTime"
            value={formData.endTime || ""}
            onChange={onChange}
            required
          />
        </label>

        <label className="full-width">
          <span>Purpose</span>
          <textarea
            name="purpose"
            value={formData.purpose || ""}
            onChange={onChange}
            rows="4"
            placeholder="Add purpose for this booking"
          />
        </label>

        <div className="form-actions full-width">
          <button type="button" className="secondary-button" onClick={onAvailabilityCheck} disabled={loading || resourceLoading}>
            {resourceLoading ? "Loading Resources..." : "Check Availability"}
          </button>
          <button type="submit" className="primary-button" disabled={loading}>
            {loading ? <span className="button-spinner" /> : "Create Booking"}
          </button>
        </div>

        {availabilityMsg ? (
          <div className="alert-box full-width">
            {safe(availabilityMsg)}
          </div>
        ) : null}
      </form>
    </div>
  );
};

export default memo(BookingForm);
